def merge_saved_broker_credentials(existing: dict[str, object], broker: str, updates: dict[str, object]) -> dict[str, object]:
    merged: dict[str, object] = dict(existing or {})
    normalized_broker = str(broker or "mstock").strip().lower() or "mstock"
    merged["broker"] = normalized_broker if normalized_broker in {"mstock", "dhan"} else "mstock"
    for key, value in (updates or {}).items():
        if value is None:
            continue
        if isinstance(value, str) and value == "":
            continue
        merged[key] = value
    return merged


def calculate_intraday_charges(
    buy_price: float,
    sell_price: float,
    quantity: int,
    *,
    is_options: bool = False,
    broker: str = "mstock",
) -> dict[str, float]:
    """Calculate round-trip intraday charges.

    Brokerage per order:
      - m.Stock options : â‚¹5 flat
      - Dhan options    : â‚¹20 flat
      - Equity (both)   : min(â‚¹20, 0.03% of value) per side
    """
    turnover = float((buy_price + sell_price) * quantity)
    buy_value = float(buy_price * quantity)
    sell_value = float(sell_price * quantity)
    if turnover <= 0 or quantity <= 0:
        return {
            "brokerage": 0.0,
            "stt": 0.0,
            "etc": 0.0,
            "sebi": 0.0,
            "stamp": 0.0,
            "gst": 0.0,
            "total": 0.0,
        }

    if is_options:
        # Brokerage differs by broker: â‚¹5 for m.Stock, â‚¹20 for Dhan
        brokerage = 5.0 if str(broker or "mstock").strip().lower() == "mstock" else 20.0
    else:
        buy_brokerage = min(20.0, buy_value * 0.0003)
        sell_brokerage = min(20.0, sell_value * 0.0003)
        brokerage = float(buy_brokerage + sell_brokerage)

    stt = float(sell_value * (0.000625 if is_options else 0.00025))
    etc = float(turnover * (0.000495 if is_options else 0.0000322))
    sebi = float(turnover * 0.000001)
    stamp = float(buy_value * (0.00005 if is_options else 0.00003))
    gst = float((brokerage + etc + sebi) * 0.18)
    total = brokerage + stt + etc + sebi + stamp + gst
    return {
        "brokerage": round(float(brokerage), 2),
        "stt": round(float(stt), 2),
        "etc": round(float(etc), 2),
        "sebi": round(float(sebi), 2),
        "stamp": round(float(stamp), 2),
        "gst": round(float(gst), 2),
        "total": round(float(total), 2),
    }


def _read_windows_registry_env(name: str, hive_name: str) -> str:
    if os.name != "nt":
        return ""


    def _safe_int_env(varname: str, default: int) -> int:
        """Safely parse an integer from environment variable with fallback."""
        try:
            v = os.getenv(varname)
            if v is None or str(v).strip() == "":
                return int(default)
            return int(str(v).strip())
        except Exception:
            try:
                return int(default)
            except Exception:
                return 0

    try:
        import winreg
    except Exception:
        return ""

    hive = getattr(winreg, hive_name, None)
    if hive is None:
        return ""

    try:
        with winreg.OpenKey(hive, r"Environment") as key:
            value, _ = winreg.QueryValueEx(key, str(name))
    except Exception:
        return ""

    try:
        return str(value or "").strip()
    except Exception:
        return ""


def _hydrate_startup_gpt_env() -> None:
    """Load GPT config into process env before the UI builds its fields.

    This keeps the GPT tab populated even when the parent process (for example,
    VS Code) was started before the user updated Windows user environment
    variables via setx.
    """

    for key in _GPT_STARTUP_ENV_KEYS:
        if str(os.getenv(key, "") or "").strip():
            continue

        value = _read_windows_registry_env(key, "HKEY_CURRENT_USER")
        if not value:
            value = _read_windows_registry_env(key, "HKEY_LOCAL_MACHINE")
        if value:
            os.environ[key] = value

    try:
        loaded = load_persisted_env(override_existing=False)
    except Exception:
        loaded = {}

    # Prefer repo-persisted GPT settings over inherited shell values.
    # This avoids stale process env keys causing intermittent 401 errors.
    for key in _GPT_STARTUP_ENV_KEYS:
        val = str(loaded.get(key, "") or "").strip()
        if val:
            os.environ[key] = val


_hydrate_startup_gpt_env()


def _apply_sv_ttk_theme(root: tk.Tk) -> None:
    """Best-effort theme setup with a safe default on Windows.

    `sv_ttk` can render as a black/blank window on some Windows setups.
    To keep the UI always usable, we default to native ttk themes on Windows
    unless the user explicitly opts in.
    """

    # Always try to keep a non-broken built-in ttk theme first.
    try:
        style = ttk.Style(root)
        names = {str(n).lower() for n in style.theme_names()}
        if "vista" in names:
            style.theme_use("vista")
        elif "clam" in names:
            style.theme_use("clam")
    except Exception:
        pass

    raw_theme = str(os.getenv("MSTOCK_UI_THEME", "") or "").strip().lower()
    explicit_theme = raw_theme in {"dark", "light"}
    use_sv_ttk_raw = str(os.getenv("MSTOCK_UI_USE_SV_TTK", "auto") or "auto").strip().lower()
    allow_sv_ttk = use_sv_ttk_raw in {"1", "true", "yes", "on"}

    # Auto policy: stick to native ttk on Windows unless explicitly opted-in.
    if not allow_sv_ttk:
        return

    try:
        import sv_ttk  # type: ignore

        theme = raw_theme if explicit_theme else ("light" if os.name == "nt" else "dark")
        sv_ttk.set_theme(theme)
    except Exception:
        return


def _apply_base_ttk_style(root: tk.Tk) -> None:
    """Apply a clean, consistent ttk style (best-effort).

    Tkinter styling varies across Windows themes; this keeps spacing/fonts
    consistent without depending on a custom theme.
    """

    try:
        default_font = ("Segoe UI", 10)
        root.option_add("*Font", default_font)
    except Exception:
        pass

    try:
        style = ttk.Style(root)
        try:
            style.configure("TLabel", padding=(0, 0, 0, 0))
            style.configure("TButton", padding=(10, 6))
            style.configure("TCheckbutton", padding=(4, 2))
            style.configure("TEntry", padding=(4, 2))
            style.configure("TLabelframe", padding=(10, 8))
            style.configure("TLabelframe.Label", font=("Segoe UI", 10, "bold"))
            style.configure("TNotebook.Tab", padding=(12, 8))
        except Exception:
            pass
    except Exception:
        pass


