class _QueueWriter:
    def __init__(self, q: queue.Queue[str]) -> None:
        self._q = q

    def write(self, s: str) -> int:
        if s:
            self._q.put(s)
        return len(s)

    def flush(self) -> None:  # pragma: no cover
        return


