        self.live_slippage_var = tk.StringVar(value="2.0")
        ttk.Entry(param_labelframe, textvariable=self.live_slippage_var, width=10).grid(row=0, column=3, padx=5, pady=5, sticky=tk.W)

        # Fee per order
