        self.live_fee_var = tk.StringVar(value="0.0")
        ttk.Entry(param_labelframe, textvariable=self.live_fee_var, width=10).grid(row=1, column=1, padx=5, pady=5, sticky=tk.W)

        # Partial fill rate
